pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the from address and a single recipient/value pair length-1 arrays
    function testFuzz_property(address from, address dummy, uint256 v0) public {
        // keep addresses non-zero to be meaningful
        vm.assume(from != address(0));
        vm.assume(dummy != address(0));

        // deploy an adversarial helper that REVERTS when called via staticcall (i.e., its fallback will revert)
        // This models a callee whose implementation makes the selector call revert when invoked under static context
        ReverterAndRejectStatic attacker = new ReverterAndRejectStatic();

        address[] memory tos = new address[](1);
        tos[0] = address(attacker);
        uint[] memory vals = new uint[](1);
        vals[0] = v0;

        // Call transfer and capture whether it completed without revert
        bool ok;
        try c.transfer(from, address(attacker), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: the reference implementation using call always returns (completes) for any callee that may reject static calls,
        // so transfer should not revert here. The mutant using staticcall can cause the call to fail for such a callee.
        // We assert that transfer did not revert (ok == true). This holds on the reference for all inputs, and the mutant fails for some inputs.
        assertTrue(ok);
    }
}

// Helper contract whose fallback will revert when invoked via staticcall (it distinguishes using gas and extcodesize is same,
// but to ensure difference we simply revert in fallback). This models a callee that does not support the staticcall semantics used by the mutant.
contract ReverterAndRejectStatic {
    fallback() external payable {
        revert("revert in fallback");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller 'from' and a single recipient/value pair packed into arrays
    function testFuzz_property(address from, address attacker, uint256 v) public {
        // admissible domain: non-zero attacker address and non-zero value to keep wide
        vm.assume(attacker != address(0));
        // arrays must be non-empty per contract's require; construct single-element arrays
        address[] memory tos = new address[](1);
        uint[] memory vals = new uint[](1);
        // Deploy an adversarial callee that will revert when invoked via staticcall
        ReverterStatic r = new ReverterStatic();
        tos[0] = address(r);
        vals[0] = v;

        // Call transfer and capture whether it returned (ok == true) or the call reverted (ok == false)
        bool ok;
        try c.transfer(from, address(r), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): the reference implementation always completes successfully
        // (returns / does not revert) for any inputs meeting the require; the mutant using staticcall
        // may cause the call to fail for callees that reject staticcall. Assert that c.transfer did not revert.
        assertTrue(ok);
    }
}

// Adversarial helper: reverts on staticcall but allows regular calls
contract ReverterStatic {
    // A regular payable fallback that does not revert when called normally
    fallback() external payable {
        // If called as a STATICCALL, opcode will force REVERT on state-changing attempts; however,
        // to ensure a difference, explicitly detect staticcall via attempting a state change and
        // reverting on failure is unnecessary here. Instead, implement a function selector that
        // reverts when invoked via staticcall by using a view modifier on a function that always reverts.
    }

    // Provide a non-payable function matching transferFrom signature that is non-view and will revert
    // when executed under staticcall contexts that disallow state changes. We implement it to revert
    // when executed as a view (static) by using an assembly STATICCALL check: since Solidity provides no
    // direct isStatic, we make a function that always reverts, but low-level call from reference will succeed
    // because non-static call context allows execution; staticcall will cause it to fail. To model the
    // differing behaviors succinctly, have this function revert unconditionally so that staticcall will return false
    // while a regular call (from the reference) using low-level call to this contract's fallback will succeed
    // because low-level call does not enforce function mutability here. To ensure low-level call succeeds,
    // we provide a payable fallback that does nothing (above). For direct function selector invocation via staticcall,
    // it will hit no matching function with view, causing failure; this suffices to create differing outcomes.

    // Provide a dummy function to match selector; but revert to make staticcall observe failure differently.
    function transferFrom(address, address, uint256) public {
        // revert to cause staticcall to fail; a low-level call to the fallback in the reference variant
        // (which encodes the same selector) will succeed because it hits fallback instead of this function.
        revert("revert in transferFrom");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from address, callee behavior selector, and a non-empty length seed
    function testFuzz_property(address from, uint8 calleeKind, uint256 lenSeed) public {
        // Keep len in [1,4] to allow arrays but remain wide
        uint256 len = bound(lenSeed, 1, 4);

        // build arrays
        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        for (uint i = 0; i < len; i++) {
            // put some valid addresses; for the adversarial callee we will deploy and use its address
            tos[i] = address(0x100 + i);
            vals[i] = i + 1;
        }

        // Deploy adversarial helper based on calldata: it will revert on staticcall but accept regular call
        // calleeKind == 0 -> benign callee that does nothing and returns
        // calleeKind == 1 -> reverts on staticcall (detects via gasleft is unreliable), implement as a fallback that reverts
        // To ensure difference between call and staticcall we implement a fallback that is payable and non-view and reverts when called via staticcall by attempting to modify state (which staticcall won't allow) OR by checking msg.data and using a modifier. Simpler: implement fallback that reverts unconditionally; but regular call from reference used call which would capture revert as failure boolean but not bubble up, still transfer continues. For staticcall mutant the staticcall will return false causing transfer to observe false. So we deploy a callee whose fallback reverts.
        AdversarialReverter adv = new AdversarialReverter();

        address target;
        if (calleeKind % 2 == 0) {
            // benign: a contract that accepts both call and staticcall (has a view fallback that returns)
            BenignC b = new BenignC();
            target = address(b);
        } else {
            // adversarial reverter: its fallback always reverts
            target = address(adv);
        }

        // route all tos to the target address so c.call/staticcall will interact with our helper
        for (uint i = 0; i < len; i++) {
            tos[i] = target;
        }

        // Call transfer and capture its success boolean by try/catch pattern on a direct external call
        bool ok;
        try c.transfer(from, target, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assert): on the reference implementation this should always be true
        // (reference uses call and swallows callee revert into a boolean, still returns true),
        // while the mutant using staticcall can cause false for adversarial reverter.
        assertTrue(ok);
    }
}

// benign callee that has a fallback which is view-like and does not revert
contract BenignC {
    fallback() external payable {
        // accept and do nothing
    }
}

// adversarial callee whose fallback always reverts
contract AdversarialReverter {
    fallback() external payable {
        revert("revert on fallback");
    }
}
